    mustMarkFlagRequired(cmd, memoryLoopAddScopeFlagKind)
    mustMarkFlagRequired(cmd, memoryLoopAddScopeFlagTitle)
    mustMarkFlagRequired(cmd, memoryLoopAddScopeFlagBody)
    return cmd
