    if err := ensureMemoryLoopStore(ctx, state); err != nil {
        return err
    }

    kind, err := parseMemoryLoopKind(opts.Kind)
    if err != nil {
        return err
    }
    scopeKind, scopeValue, ownerEmail, err := resolveAddScope(ctx, opts.Scope)
    if err != nil {
        return err
    }

    records, added, err := memoryloop.AddManualRecord(state.Store.Records, memoryloop.ManualRecordInput{
        Kind:       kind,
        Title:      opts.Title,
        Body:       opts.Body,
        ScopeKind:  scopeKind,
        ScopeValue: scopeValue,
        OwnerEmail: ownerEmail,
    }, time.Now().UTC())
    if err != nil {
        return fmt.Errorf("add manual memory: %w", err)
    }

    state.Store.Records = records
    if err := memoryloop.SaveState(ctx, state); err != nil {
        return fmt.Errorf("save memory-loop state: %w", err)
    }

    fmt.Fprintf(w, "Added memory: %s\n", added.ID)
    return nil
}
```

**Pattern for save_memory**:
1. Load state with `memoryloop.LoadState(ctx)`
2. Ensure store exists with `ensureMemoryLoopStore(ctx, state)`
3. Validate/parse inputs (kind, scope)
4. Call memoryloop package function with validated inputs + timestamp
5. Update `state.Store.Records`
6. Save with `memoryloop.SaveState(ctx, state)`
7. Output result

